-- 017: Tamil corrections from MotoLend_Missing_Tamil_Translations.docx.
--
-- Text found still in English (or with different Tamil) in Tamil mode. Kept
-- as its own sheet: where it has a value, that value wins over the workbook's
-- sheets (see frontend/src/i18n/tamil.js). Each English key is the exact text
-- the app shows; ${…} marks a live value such as a count or loan number.
-- Matches the same sheet in frontend/src/i18n/motolendTamil.js.

ON CONFLICT (sheet, english) DO UPDATE SET tamil = EXCLUDED.tamil, updated_at = now();
